#ifndef PC_NL_UI_H
#define PC_NL_UI_H

/* New Leaf UI: windows and menus redrawn with art pre-rendered from New Leaf's own layouts
 * (generated by asset_import_work/nl_ui_survey/gen_nlui.py into pc_nl_ui_data.c). */

#include "types.h"
#include "PR/gbi.h"
#include "m_lib.h"
#include "graph.h"

int pc_nlui_enabled(void);

/* Dialogue window. All draw in the message window's model space (pixels * 16, origin at the window centre). */
Gfx* pc_nlui_msg_box(GRAPH* graph, Gfx* g, int alpha);
Gfx* pc_nlui_msg_plate(GRAPH* graph, Gfx* g, f32 text_x, f32 text_w, rgba_t* color);
Gfx* pc_nlui_msg_arrow(GRAPH* graph, Gfx* g, int alpha);
/* Text colour on the dark NL window: GameCube's default dark text becomes white, other colours are lightened. */
void pc_nlui_msg_text_color(rgba_t* out, const rgba_t* in);

/* Choice window: box in the display-scaled window space, cursor/underline in the choice font space. */
/* NL choice window placement (screen pixels): padding around the options, and where its right/bottom edges sit
 * (just above the top-right of the dialogue window). */
#define NLUI_CHOICE_PAD_L 17.0f
#define NLUI_CHOICE_PAD_R 19.0f
#define NLUI_CHOICE_PAD_T 5.0f
#define NLUI_CHOICE_PAD_B 13.0f
#define NLUI_CHOICE_SCALE 0.65f   /* options + box drawn at this uniform scale (GameCube squashes them instead) */
#define NLUI_CHOICE_RIGHT 298.0f
#define NLUI_CHOICE_BOTTOM 150.0f
Gfx* pc_nlui_choice_rect(GRAPH* graph, Gfx* g, f32 x0, f32 y0, f32 x1, f32 y1, f32 sx, f32 sy, int alpha);
Gfx* pc_nlui_choice_box(GRAPH* graph, Gfx* g, f32 w, f32 h, f32 sx, f32 sy, int alpha);
Gfx* pc_nlui_choice_cursor(GRAPH* graph, Gfx* g, f32 x, f32 y);
Gfx* pc_nlui_choice_underline(GRAPH* graph, Gfx* g, f32 x, f32 y, f32 w);

/* Item name tag, in the tag's pixel-unit space. */
Gfx* pc_nlui_tag_balloon(GRAPH* graph, Gfx* g, f32 w, f32 h);
Gfx* pc_nlui_tag_tail(GRAPH* graph, Gfx* g, int mirror);

#endif
